#include <zephyr/device.h>
#include <zephyr/drivers/can.h> 
#include <zephyr/kernel.h>
#include <zephyr/ztest.h>

#define CAN_DEV DT_ALIAS(can_dev)

/*
 * The CAN bitrate is not part of the CAN API, but it is required for the tests to run.
 * The bitrate is set to a default value, but can be overridden by the board.
 */
#ifndef CAN_BITRATE
#define CAN_BITRATE 250000
#endif

#ifndef CAN_BITRATE_DATA
#define CAN_BITRATE_DATA 1000000
#endif

#define CAN_SJW 0

#define RX_THREAD_STACK_SIZE 512
#define RX_THREAD_PRIORITY 2

#define TX_TIMEOUT_MS 100
#define RX_TIMEOUT_MS 100

const static struct can_filter test_filter = {
	.flags = CAN_FILTER_IDE,
	.id = 0x123,
	.mask = CAN_EXT_ID_MASK,
};

K_THREAD_STACK_DEFINE(rx_thread_stack, RX_THREAD_STACK_SIZE);
static struct k_thread rx_thread_data;
static K_SEM_DEFINE(rx_sem, 0, 1);
static K_SEM_DEFINE(tx_callback_sem, 0, 1);
static struct can_frame rx_frame;
static k_tid_t rx_tid;

static void tx_callback(const struct device *dev, int error, void *user_data)
{
	const struct can_frame *frame = user_data;

	zassert_equal(dev, DEVICE_DT_GET(CAN_DEV), "dev ptr mismatch");
	zassert_equal(frame->id, 0x456, "frame id mismatch");
	zassert_ok(error, "TX callback error");

	k_sem_give(&tx_callback_sem);
}

static void rx_thread(void *arg1, void *arg2, void *arg3)
{
	const struct device *can_dev = arg1;
	struct can_frame frame;
	int filter_id;
	int err;

	filter_id = can_add_rx_filter(can_dev, &test_filter, NULL);
	zassert_not_equal(filter_id, -1, "failed to add rx filter");

	while (1) {
		err = can_receive(can_dev, &frame, K_MSEC(RX_TIMEOUT_MS), NULL);
		if (err == -EAGAIN) {
			continue;
		}
		zassert_ok(err, "failed to receive frame");

		if (frame.id == test_filter.id) {
			memcpy(&rx_frame, &frame, sizeof(rx_frame));
			k_sem_give(&rx_sem);
		}
	}
}

ZTEST(can_api, test_bitrate_limits)
{
	const struct device *const can_dev = DEVICE_DT_GET(CAN_DEV);

	zassert_true(device_is_ready(can_dev), "CAN device not ready");

	zassert_ok(can_set_bitrate(can_dev, 125000), "failed to set bitrate");
	zassert_ok(can_set_bitrate(can_dev, 1000000), "failed to set bitrate");
}

ZTEST(can_api, test_classic_get_capabilities)
{
	const struct device *const can_dev = DEVICE_DT_GET(CAN_DEV);
	uint32_t cap;

	zassert_true(device_is_ready(can_dev), "CAN device not ready");

	zassert_ok(can_get_capabilities(can_dev, &cap), "failed to get capabilities");
	zassert_not_equal(cap, 0, "no capabilities reported");
}

ZTEST(can_api, test_filters_added_while_stopped)
{
	const struct device *const can_dev = DEVICE_DT_GET(CAN_DEV);
	int filter_id;

	zassert_true(device_is_ready(can_dev), "CAN device not ready");

	filter_id = can_add_rx_filter(can_dev, &test_filter, NULL);
	zassert_not_equal(filter_id, -1, "failed to add filter");

	can_remove_rx_filter(can_dev, filter_id);
}

ZTEST(can_api, test_filters_preserved_through_bitrate_change)
{
	const struct device *const can_dev = DEVICE_DT_GET(CAN_DEV);
	int filter_id;

	zassert_true(device_is_ready(can_dev), "CAN device not ready");

	filter_id = can_add_rx_filter(can_dev, &test_filter, NULL);
	zassert_not_equal(filter_id, -1, "failed to add filter");

	zassert_ok(can_set_bitrate(can_dev, CAN_BITRATE), "failed to set bitrate");

	can_remove_rx_filter(can_dev, filter_id);
}

ZTEST(can_api, test_filters_preserved_through_mode_change)
{
	const struct device *const can_dev = DEVICE_DT_GET(CAN_DEV);
	int filter_id;

	zassert_true(device_is_ready(can_dev), "CAN device not ready");

	filter_id = can_add_rx_filter(can_dev, &test_filter, NULL);
	zassert_not_equal(filter_id, -1, "failed to add filter");

	zassert_ok(can_set_mode(can_dev, CAN_MODE_LOOPBACK), "failed to set mode");

	can_remove_rx_filter(can_dev, filter_id);
}

ZTEST(can_api, test_get_core_clock)
{
	const struct device *const can_dev = DEVICE_DT_GET(CAN_DEV);
	uint32_t rate;

	zassert_true(device_is_ready(can_dev), "CAN device not ready");

	zassert_ok(can_get_core_clock(can_dev, &rate), "failed to get core clock");
	zassert_not_equal(rate, 0, "core clock is 0");
}

ZTEST(can_api, test_get_state)
{
	const struct device *const can_dev = DEVICE_DT_GET(CAN_DEV);
	enum can_state state;
	struct can_bus_err_cnt err_cnt;
	uint32_t cap;

	zassert_true(device_is_ready(can_dev), "CAN device not ready");

	zassert_ok(can_get_capabilities(can_dev, &cap), "failed to get capabilities");
	if ((cap & CAN_CAP_GET_STATE) == 0) {
		ztest_test_skip();
	}

	zassert_ok(can_get_state(can_dev, &state, &err_cnt), "failed to get CAN state");
	zassert_equal(state, CAN_STATE_STOPPED, "CAN controller not in stopped state");
	zassert_equal(err_cnt.tx_err_cnt, 0, "TX error counter not 0");
	zassert_equal(err_cnt.rx_err_cnt, 0, "RX error counter not 0");

	zassert_ok(can_start(can_dev), "failed to start CAN controller");

	zassert_ok(can_get_state(can_dev, &state, NULL), "failed to get CAN state");
	zassert_equal(state, CAN_STATE_ERROR_ACTIVE, "CAN controller not in error active state");

	zassert_ok(can_get_state(can_dev, &state, &err_cnt), "failed to get CAN state");
	zassert_equal(state, CAN_STATE_ERROR_ACTIVE, "CAN controller not in error active state");
	zassert_equal(err_cnt.tx_err_cnt, 0, "TX error counter not 0");
	zassert_equal(err_cnt.rx_err_cnt, 0, "RX error counter not 0");

	zassert_ok(can_stop(can_dev), "failed to stop CAN controller");

	zassert_ok(can_get_state(can_dev, &state, &err_cnt), "failed to get CAN state");
	zassert_equal(state, CAN_STATE_STOPPED, "CAN controller not in stopped state");
	zassert_equal(err_cnt.tx_err_cnt, 0, "TX error counter not 0");
	zassert_equal(err_cnt.rx_err_cnt, 0, "RX error counter not 0");
}

static void *can_api_setup(void)
{
	const struct device *can_dev = DEVICE_DT_GET(CAN_DEV);

	zassert_true(device_is_ready(can_dev), "CAN device not ready");

	(void)can_stop(can_dev);

	return NULL;
}

ZTEST_SUITE(can_api, NULL, can_api_setup, NULL, NULL, NULL);
